UPDATE data_pull_log
SET status = 'FAILED',
    error_message = '任务超时未完成，可能进程异常退出',
    end_time = #{currentTime}
WHERE status = 'RUNNING'
AND start_time < #{cutoffTime}

mapper.select:
SELECT l.id, l.task_id, l.table_code, l.table_name, l.operation_type, l.status, l.start_time, l.end_time, l.duration_ms, l.total_count, l.error_message, l.operator FROM data_pull_log l INNER JOIN ( SELECT table_code, MAX(start_time) AS max_start FROM data_pull_log WHERE table_code IN
#{tc}
GROUP BY table_code ) latest ON l.table_code = latest.table_code AND l.start_time = latest.max_start
